// The two Open-Meteo feeds + the stored profile
const weather = $('Fetch Weather & UV').first().json;
const air = $('Fetch Air Quality & Pollen').first().json;
const profile = $('My Profile').first().json;

const cur = weather.current || {};
const daily = weather.daily || {};
const hourly = weather.hourly || {};
const airCur = air.current || {};

const round1 = (value) => (typeof value === 'number' ? Math.round(value * 10) / 10 : value);
const hhmm = (iso) => (iso ? String(iso).slice(11, 16) : 'n/a');

// --- the hour with the strongest UV today ---
const today = (daily.time && daily.time[0]) || String(cur.time || '').slice(0, 10);
const times = hourly.time || [];
const uvSeries = hourly.uv_index || [];
let peakUv = null;
let peakUvTime = null;
for (let i = 0; i < times.length; i++) {
  if (today && String(times[i]).slice(0, 10) !== today) continue;
  const value = uvSeries[i];
  if (value === null || value === undefined) continue;
  if (peakUv === null || value > peakUv) {
    peakUv = value;
    peakUvTime = times[i];
  }
}

// --- European AQI band ---
const aqi = airCur.european_aqi;
const aqiBand = (value) => {
  if (value === null || value === undefined) return 'unknown';
  if (value <= 20) return 'good';
  if (value <= 40) return 'fair';
  if (value <= 60) return 'moderate';
  if (value <= 80) return 'poor';
  if (value <= 100) return 'very poor';
  return 'extremely poor';
};

// --- strongest pollen of the day (grains/m3) ---
const pollens = {
  alder: airCur.alder_pollen,
  birch: airCur.birch_pollen,
  grass: airCur.grass_pollen,
  mugwort: airCur.mugwort_pollen,
  ragweed: airCur.ragweed_pollen,
};
let topPollenType = null;
let topPollenValue = null;
const pollenNames = Object.keys(pollens);
for (let i = 0; i < pollenNames.length; i++) {
  const name = pollenNames[i];
  const value = pollens[name];
  if (value === null || value === undefined) continue;
  if (topPollenValue === null || value > topPollenValue) {
    topPollenValue = value;
    topPollenType = name;
  }
}
const pollenBand = (value) => {
  if (value === null || value === undefined) return 'no data';
  if (value < 10) return 'low';
  if (value < 50) return 'moderate';
  return 'high';
};

return [
  {
    json: {
      date: today,
      location: weather.timezone || '',
      sunrise: hhmm(daily.sunrise && daily.sunrise[0]),
      sunset: hhmm(daily.sunset && daily.sunset[0]),
      temperatureC: round1(cur.temperature_2m),
      feelsLikeC: round1(cur.apparent_temperature),
      cloudCoverPct: cur.cloud_cover,
      humidityPct: cur.relative_humidity_2m,
      uvIndexNow: round1(cur.uv_index),
      uvIndexMaxToday: round1(daily.uv_index_max && daily.uv_index_max[0]),
      peakUvHour: hhmm(peakUvTime),
      pm25: round1(airCur.pm2_5),
      pm10: round1(airCur.pm10),
      dust: round1(airCur.dust),
      europeanAqi: aqi,
      airQualityLevel: aqiBand(aqi),
      topPollenType: topPollenType,
      topPollenValue: round1(topPollenValue),
      pollenLevel: pollenBand(topPollenValue),
      healthFocus: profile.healthFocus,
    },
  },
];

const LF = String.fromCharCode(10);
const CR = String.fromCharCode(13);
const TAB = String.fromCharCode(9);
const BS = String.fromCharCode(92);

const briefingInputs = $input.first().json;
const icsRaw = String(($("Fetch Schedule (iCal)").first().json.data) || "");

// unfold RFC 5545 folded lines (continuation lines start with a space or tab)
const unfolded = icsRaw.split(CR + LF).join(LF).split(LF + " ").join("").split(LF + TAB).join("");

const unescapeIcs = (value) => {
  let out = String(value === null || value === undefined ? "" : value);
  out = out.split(BS + "n").join(" ");
  out = out.split(BS + "N").join(" ");
  out = out.split(BS + ",").join(",");
  out = out.split(BS + ";").join(";");
  out = out.split(BS + BS).join(BS);
  return out.trim();
};

// Europe/Amsterdam (same DST rule as Europe/Brussels) offset from UTC, in hours
const lastSundayOfMonth = (year, month) => {
  const last = new Date(Date.UTC(year, month, 0));
  return last.getUTCDate() - last.getUTCDay();
};
const localOffsetHours = (utcMillis) => {
  const d = new Date(utcMillis);
  const year = d.getUTCFullYear();
  const dstStart = Date.UTC(year, 2, lastSundayOfMonth(year, 3), 1, 0, 0);
  const dstEnd = Date.UTC(year, 9, lastSundayOfMonth(year, 10), 1, 0, 0);
  return utcMillis >= dstStart && utcMillis < dstEnd ? 2 : 1;
};

const parseIcsDate = (raw) => {
  const value = String(raw === null || raw === undefined ? "" : raw).trim();
  if (value.length < 8) return null;
  const year = Number(value.slice(0, 4));
  const month = Number(value.slice(4, 6));
  const day = Number(value.slice(6, 8));
  if (!year || !month || !day) return null;
  if (value.length >= 15 && value.charAt(8) === "T") {
    return {
      dateOnly: false,
      year: year,
      month: month,
      day: day,
      hour: Number(value.slice(9, 11)),
      minute: Number(value.slice(11, 13)),
      second: Number(value.slice(13, 15)),
      isUtc: value.charAt(value.length - 1) === "Z",
    };
  }
  return { dateOnly: true, year: year, month: month, day: day, hour: 0, minute: 0, second: 0, isUtc: true };
};

const toMillis = (parsed) => {
  const naive = Date.UTC(parsed.year, parsed.month - 1, parsed.day, parsed.hour || 0, parsed.minute || 0, parsed.second || 0);
  if (parsed.isUtc) return naive;
  // wall-clock time in the local zone: subtract the offset for that day (re-check once for DST edges)
  const guess = naive - localOffsetHours(naive) * 3600000;
  return naive - localOffsetHours(guess) * 3600000;
};

const localHhmm = (millis) => {
  const local = new Date(millis + localOffsetHours(millis) * 3600000);
  const hh = String(local.getUTCHours());
  const mm = String(local.getUTCMinutes());
  return (hh.length < 2 ? "0" + hh : hh) + ":" + (mm.length < 2 ? "0" + mm : mm);
};

const todayIsoDate = $now.setZone("Europe/Amsterdam").toISODate();
const todayParts = todayIsoDate.split("-");
const dayStartNaive = Date.UTC(Number(todayParts[0]), Number(todayParts[1]) - 1, Number(todayParts[2]), 0, 0, 0);
const dayStart = dayStartNaive - localOffsetHours(dayStartNaive) * 3600000;
const dayEnd = dayStart + 24 * 3600000;

const blocks = unfolded.split("BEGIN:VEVENT");
const classes = [];
for (let i = 1; i < blocks.length; i++) {
  const body = blocks[i].split("END:VEVENT")[0];
  const lines = body.split(LF);
  const readField = (name) => {
    for (let j = 0; j < lines.length; j++) {
      const line = lines[j];
      if (line.indexOf(name + ":") === 0 || line.indexOf(name + ";") === 0) {
        return line.slice(line.indexOf(":") + 1);
      }
    }
    return null;
  };

  const start = parseIcsDate(readField("DTSTART"));
  if (!start) continue;
  const startMillis = toMillis(start);
  const endParsed = parseIcsDate(readField("DTEND"));
  const endMillis = endParsed ? toMillis(endParsed) : startMillis + 3600000;
  if (endMillis <= dayStart || startMillis >= dayEnd) continue;

  // the class type lives on the first description line, before the escapes are resolved
  const rawDescription = String(readField("DESCRIPTION") || "");
  const rawDescriptionLines = rawDescription.split(BS + "n");
  let type = "";
  for (let j = 0; j < rawDescriptionLines.length; j++) {
    const descriptionLine = unescapeIcs(rawDescriptionLines[j]);
    if (descriptionLine.indexOf("Type:") === 0) {
      type = descriptionLine.slice(5).trim();
      break;
    }
  }

  classes.push({
    sortKey: startMillis,
    start: localHhmm(startMillis),
    end: localHhmm(endMillis),
    title: unescapeIcs(readField("SUMMARY")) || "Untitled",
    location: unescapeIcs(readField("LOCATION")),
    type: type,
  });
}
classes.sort((a, b) => a.sortKey - b.sortKey);

const scheduleLines = [];
for (let i = 0; i < classes.length; i++) {
  const c = classes[i];
  let entry = "- " + c.start + "-" + c.end + " " + c.title;
  if (c.location) entry = entry + " @ " + c.location;
  if (c.type) entry = entry + " (" + c.type + ")";
  scheduleLines.push(entry);
}
const scheduleText = classes.length > 0 ? scheduleLines.join(LF) : "No classes scheduled today.";

return [
  {
    json: {
      latitude: briefingInputs.latitude,
      longitude: briefingInputs.longitude,
      date: briefingInputs.date,
      location: briefingInputs.location,
      sunrise: briefingInputs.sunrise,
      sunset: briefingInputs.sunset,
      temperatureC: briefingInputs.temperatureC,
      feelsLikeC: briefingInputs.feelsLikeC,
      cloudCoverPct: briefingInputs.cloudCoverPct,
      humidityPct: briefingInputs.humidityPct,
      uvIndexNow: briefingInputs.uvIndexNow,
      uvIndexMaxToday: briefingInputs.uvIndexMaxToday,
      peakUvHour: briefingInputs.peakUvHour,
      pm25: briefingInputs.pm25,
      pm10: briefingInputs.pm10,
      dust: briefingInputs.dust,
      europeanAqi: briefingInputs.europeanAqi,
      airQualityLevel: briefingInputs.airQualityLevel,
      topPollenType: briefingInputs.topPollenType,
      topPollenValue: briefingInputs.topPollenValue,
      pollenLevel: briefingInputs.pollenLevel,
      healthFocus: briefingInputs.healthFocus,
      classCount: classes.length,
      firstClassStart: classes.length > 0 ? classes[0].start : "",
      firstClassName: classes.length > 0 ? classes[0].title : "",
      lastClassEnd: classes.length > 0 ? classes[classes.length - 1].end : "",
      scheduleText: scheduleText,
    },
  },
];
